INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_038_M2_S2', 'piston', '2', 'piston refers to a reciprocating engine component that transfers gas pressure to the connecting rod and crank mechanism. In Engine Components and Mechanics, the focus is on the analysis, design, implementation, interpretation, or evaluation of piston within Internal Combustion Engines, particularly where the Engine Components and Mechanics module establishes its technical context.', 'SSD_COURSE_038_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M2_S3', 'crankshaft', '3', 'crankshaft refers to a rotating shaft that converts piston reciprocating motion into useful rotary output. In Engine Components and Mechanics, the focus is on the analysis, design, implementation, interpretation, or evaluation of crankshaft within Internal Combustion Engines, particularly where the Engine Components and Mechanics module establishes its technical context.', 'SSD_COURSE_038_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M2_S4', 'valve train', '4', 'valve train refers to the components that open and close engine intake and exhaust valves at controlled times. In Engine Components and Mechanics, the focus is on the analysis, design, implementation, interpretation, or evaluation of valve train within Internal Combustion Engines, particularly where the Engine Components and Mechanics module establishes its technical context.', 'SSD_COURSE_038_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M2_S5', 'lubrication', '5', 'lubrication: Supplying lubricant to engine surfaces to reduce friction, wear, and heat generation. In Engine Components and Mechanics, the focus is on the analysis, design, implementation, interpretation, or evaluation of lubrication within Internal Combustion Engines, particularly where the Engine Components and Mechanics module establishes its technical context.', 'SSD_COURSE_038_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M2_S6', 'cooling', '6', 'cooling: Removing excess engine heat to maintain components and lubricant within acceptable operating temperatures. In Engine Components and Mechanics, the focus is on the analysis, design, implementation, interpretation, or evaluation of cooling within Internal Combustion Engines, particularly where the Engine Components and Mechanics module establishes its technical context.', 'SSD_COURSE_038_M2_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M3_S1', 'air intake', '1', 'air intake refers to the path and process by which fresh air is supplied to the engine cylinders. In Air and Fuel Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of air intake within Internal Combustion Engines, particularly where the Air and Fuel Systems module establishes its technical context.', 'SSD_COURSE_038_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M3_S2', 'turbocharging', '2', 'turbocharging: Using a turbine-driven compressor to increase intake-air pressure and engine air mass flow. In Air and Fuel Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of turbocharging within Internal Combustion Engines, particularly where the Air and Fuel Systems module establishes its technical context.', 'SSD_COURSE_038_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M3_S3', 'fuel injection', '3', 'fuel injection: Metering and delivering fuel into the intake or combustion chamber at controlled timing and conditions. In Air and Fuel Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of fuel injection within Internal Combustion Engines, particularly where the Air and Fuel Systems module establishes its technical context.', 'SSD_COURSE_038_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M3_S4', 'ignition', '4', 'ignition: Initiation of combustion in a fuel-air mixture by a spark or by conditions that cause autoignition. In Air and Fuel Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of ignition within Internal Combustion Engines, particularly where the Air and Fuel Systems module establishes its technical context.', 'SSD_COURSE_038_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M3_S5', 'mixture formation', '5', 'mixture formation: Preparation and distribution of the fuel-air mixture required for combustion. In Air and Fuel Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of mixture formation within Internal Combustion Engines, particularly where the Air and Fuel Systems module establishes its technical context.', 'SSD_COURSE_038_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M4_S1', 'flame development', '1', 'flame development: Early propagation of a combustion flame after ignition in a spark-ignition engine. In Combustion in Engines, the focus is on the analysis, design, implementation, interpretation, or evaluation of flame development within Internal Combustion Engines, particularly where the Combustion in Engines module establishes its technical context.', 'SSD_COURSE_038_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M4_S2', 'ignition delay', '2', 'ignition delay refers to the interval between fuel injection and the start of significant combustion in a compression-ignition engine. In Combustion in Engines, the focus is on the analysis, design, implementation, interpretation, or evaluation of ignition delay within Internal Combustion Engines, particularly where the Combustion in Engines module establishes its technical context.', 'SSD_COURSE_038_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M4_S3', 'knock', '3', 'knock: Unwanted rapid combustion or pressure oscillation caused by abnormal autoignition in an engine cylinder. In Combustion in Engines, the focus is on the analysis, design, implementation, interpretation, or evaluation of knock within Internal Combustion Engines, particularly where the Combustion in Engines module establishes its technical context.', 'SSD_COURSE_038_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M4_S4', 'combustion efficiency', '4', 'combustion efficiency refers to a measure of how effectively the chemical energy of fuel is converted through combustion, considering incomplete combustion losses. In Combustion in Engines, the focus is on the analysis, design, implementation, interpretation, or evaluation of combustion efficiency within Internal Combustion Engines, particularly where the Combustion in Engines module establishes its technical context.', 'SSD_COURSE_038_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M4_S5', 'heat release', '5', 'heat release: Rate and total amount of chemical energy released during combustion as the fuel–air mixture reacts. In Combustion in Engines, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat release within Internal Combustion Engines, particularly where the Combustion in Engines module establishes its technical context.', 'SSD_COURSE_038_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M5_S1', 'brake power', '1', 'brake power: Useful mechanical power available at an engine''s output shaft, measured after internal mechanical losses. In Engine Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of brake power within Internal Combustion Engines, particularly where the Engine Performance module establishes its technical context.', 'SSD_COURSE_038_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M5_S2', 'indicated power', '2', 'indicated power: Power developed by the gases on the engine pistons, calculated from in-cylinder pressure and displacement or from related indicated work. In Engine Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of indicated power within Internal Combustion Engines, particularly where the Engine Performance module establishes its technical context.', 'SSD_COURSE_038_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M5_S3', 'efficiency', '3', 'efficiency: Ratio or other defined measure of useful output to input for a process, device, or system under specified operating conditions. In Engine Performance, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_038_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M5_S4', 'specific fuel consumption', '4', 'specific fuel consumption: Fuel mass consumed per unit of useful engine power over a specified operating period. In Engine Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of specific fuel consumption within Internal Combustion Engines, particularly where the Engine Performance module establishes its technical context.', 'SSD_COURSE_038_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M5_S5', 'performance testing', '5', 'performance testing: Measurement of engine operating variables such as power, torque, fuel consumption, efficiency, and emissions under controlled test conditions. In Engine Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of performance testing within Internal Combustion Engines, particularly where the Engine Performance module establishes its technical context.', 'SSD_COURSE_038_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M6_S1', 'NOx', '1', 'NOx: Nitrogen oxides formed mainly through high-temperature combustion processes and relevant to engine emissions control. In Emissions and After-Treatment, the focus is on the analysis, design, implementation, interpretation, or evaluation of NOx within Internal Combustion Engines, particularly where the Emissions and After-Treatment module establishes its technical context.', 'SSD_COURSE_038_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M6_S2', 'particulate matter', '2', 'particulate matter: Fine solid or liquid particles emitted from combustion, especially significant in diesel engines. In Emissions and After-Treatment, the focus is on the analysis, design, implementation, interpretation, or evaluation of particulate matter within Internal Combustion Engines, particularly where the Emissions and After-Treatment module establishes its technical context.', 'SSD_COURSE_038_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M6_S3', 'Carbon Monoxide (CO)', '3', 'CO: Carbon monoxide produced by incomplete combustion and emitted in engine exhaust. In Emissions and After-Treatment, the focus is on the analysis, design, implementation, interpretation, or evaluation of CO within Internal Combustion Engines, particularly where the Emissions and After-Treatment module establishes its technical context.', 'SSD_COURSE_038_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M6_S4', 'hydrocarbons', '4', 'hydrocarbons: Unburned or partially oxidised fuel-related compounds present in engine exhaust. In Emissions and After-Treatment, the focus is on the analysis, design, implementation, interpretation, or evaluation of hydrocarbons within Internal Combustion Engines, particularly where the Emissions and After-Treatment module establishes its technical context.', 'SSD_COURSE_038_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M6_S5', 'oxidation catalysts', '5', 'oxidation catalysts: After-treatment catalysts that promote oxidation of carbon monoxide and hydrocarbons in exhaust gas. In Emissions and After-Treatment, the focus is on the analysis, design, implementation, interpretation, or evaluation of oxidation catalysts within Internal Combustion Engines, particularly where the Emissions and After-Treatment module establishes its technical context.', 'SSD_COURSE_038_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M6_S6', 'particulate filters', '6', 'particulate filters: Exhaust after-treatment devices that capture particulate matter and periodically remove accumulated soot. In Emissions and After-Treatment, the focus is on the analysis, design, implementation, interpretation, or evaluation of particulate filters within Internal Combustion Engines, particularly where the Emissions and After-Treatment module establishes its technical context.', 'SSD_COURSE_038_M6_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M7_S1', 'electronic control', '1', 'electronic control: Use of electronic sensors, controllers, actuators, and control logic to regulate engine operating conditions. In Engine Control and Diagnostics, the focus is on the analysis, design, implementation, interpretation, or evaluation of electronic control within Internal Combustion Engines, particularly where the Engine Control and Diagnostics module establishes its technical context.', 'SSD_COURSE_038_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M7_S2', 'sensors', '2', 'sensors: Devices that measure engine variables such as pressure, temperature, speed, oxygen concentration, or position. In Engine Control and Diagnostics, the focus is on the analysis, design, implementation, interpretation, or evaluation of sensors within Internal Combustion Engines, particularly where the Engine Control and Diagnostics module establishes its technical context.', 'SSD_COURSE_038_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M7_S3', 'actuators', '3', 'actuators: Devices that convert a control signal or available energy into physical action, such as force, motion, flow, pressure, or position. In Engine Control and Diagnostics, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_038_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M7_S4', 'diagnostics', '4', 'diagnostics: Methods for detecting and identifying engine faults using measured signals, operating data, and system models. In Engine Control and Diagnostics, the focus is on the analysis, design, implementation, interpretation, or evaluation of diagnostics within Internal Combustion Engines, particularly where the Engine Control and Diagnostics module establishes its technical context.', 'SSD_COURSE_038_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_038_M7_S5', 'Engine calibration', '5', 'Engine calibration: Adjustment and validation of engine control parameters and maps so that the engine meets specified performance, emissions, drivability, and operating constraints across its intended operating range. In Engine Control and Diagnostics, the focus is on internal Combustion Engines → Engine Control and Diagnostics: calibration of control parameters and maps, validation against performance and emissions constraints, and operating-range considerations.', 'SSD_COURSE_038_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M1_S1', 'crystal structures', '1', 'crystal structures: Ordered arrangements of atoms in crystalline materials that strongly influence their mechanical, thermal, and physical properties. In Material Structure and Properties, the focus is on the analysis, design, implementation, interpretation, or evaluation of crystal structures within Engineering Materials, particularly where the Material Structure and Properties module establishes its technical context.', 'SSD_COURSE_039_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M1_S2', 'defects', '2', 'defects: Imperfections such as vacancies, dislocations, and grain boundaries that affect material behaviour and processing. In Material Structure and Properties, the focus is on the analysis, design, implementation, interpretation, or evaluation of defects within Engineering Materials, particularly where the Material Structure and Properties module establishes its technical context.', 'SSD_COURSE_039_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M1_S3', 'diffusion', '3', 'diffusion: Movement of atoms or molecules through a material driven primarily by concentration or chemical-potential gradients. In Material Structure and Properties, the focus is on the analysis, design, implementation, interpretation, or evaluation of diffusion within Engineering Materials, particularly where the Material Structure and Properties module establishes its technical context.', 'SSD_COURSE_039_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M1_S4', 'phase structure', '4', 'phase structure refers to the phases present in a material and their distribution, composition, and relationships at equilibrium or during processing. In Material Structure and Properties, the focus is on the analysis, design, implementation, interpretation, or evaluation of phase structure within Engineering Materials, particularly where the Material Structure and Properties module establishes its technical context.', 'SSD_COURSE_039_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M1_S5', 'mechanical properties', '5', 'mechanical properties: Material characteristics such as strength, stiffness, ductility, toughness, hardness, and fatigue resistance. In Material Structure and Properties, the focus is on the analysis, design, implementation, interpretation, or evaluation of mechanical properties within Engineering Materials, particularly where the Material Structure and Properties module establishes its technical context.', 'SSD_COURSE_039_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M2_S1', 'steels', '1', 'steels: Iron-carbon alloys containing controlled additions of other elements and widely used for structural and mechanical applications. In Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of steels within Engineering Materials, particularly where the Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M2_S2', 'cast irons', '2', 'cast irons: Iron-carbon alloys with relatively high carbon content that are commonly cast into complex shapes. In Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of cast irons within Engineering Materials, particularly where the Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M2_S3', 'phase transformations', '3', 'phase transformations: Changes from one material phase or microstructural state to another caused by temperature, composition, or processing. In Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of phase transformations within Engineering Materials, particularly where the Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M2_S4', 'heat treatment', '4', 'heat treatment: Controlled heating and cooling of a material to change its microstructure and obtain desired mechanical or physical properties. In Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat treatment within Engineering Materials, particularly where the Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M2_S5', 'alloying', '5', 'alloying: Adding elements to a base material to modify its structure and properties. In Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of alloying within Engineering Materials, particularly where the Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M3_S1', 'aluminium', '1', 'aluminium refers to a lightweight metal valued for low density, corrosion resistance, and useful strength-to-weight performance. In Non-Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of aluminium within Engineering Materials, particularly where the Non-Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M3_S2', 'copper', '2', 'copper refers to a highly conductive metal widely used in electrical, thermal, and engineering applications. In Non-Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of copper within Engineering Materials, particularly where the Non-Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M3_S3', 'titanium', '3', 'titanium refers to a high-strength, low-density metal with excellent corrosion resistance and useful performance at elevated temperatures. In Non-Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of titanium within Engineering Materials, particularly where the Non-Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M3_S4', 'nickel alloys', '4', 'nickel alloys: Alloys based on nickel that retain strength and corrosion resistance in demanding or high-temperature environments. In Non-Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of nickel alloys within Engineering Materials, particularly where the Non-Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M3_S5', 'selection criteria', '5', 'selection criteria: Material properties, service conditions, manufacturing requirements, cost, and other constraints used to compare candidate materials. In Non-Ferrous Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of selection criteria within Engineering Materials, particularly where the Non-Ferrous Materials module establishes its technical context.', 'SSD_COURSE_039_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M4_S1', 'thermoplastics', '1', 'thermoplastics: Polymers that soften when heated and can generally be reheated and reshaped. In Polymers and Ceramics, the focus is on the analysis, design, implementation, interpretation, or evaluation of thermoplastics within Engineering Materials, particularly where the Polymers and Ceramics module establishes its technical context.', 'SSD_COURSE_039_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M4_S2', 'thermosets', '2', 'thermosets: Polymers that form a permanently cross-linked structure during curing and cannot be remelted into a new shape. In Polymers and Ceramics, the focus is on the analysis, design, implementation, interpretation, or evaluation of thermosets within Engineering Materials, particularly where the Polymers and Ceramics module establishes its technical context.', 'SSD_COURSE_039_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M4_S3', 'elastomers', '3', 'elastomers: Polymers capable of large reversible elastic deformation. In Polymers and Ceramics, the focus is on the analysis, design, implementation, interpretation, or evaluation of elastomers within Engineering Materials, particularly where the Polymers and Ceramics module establishes its technical context.', 'SSD_COURSE_039_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_039_M4_S4', 'ceramics', '4', 'ceramics: Inorganic non-metallic materials generally characterised by high hardness, temperature resistance, and brittleness. In Polymers and Ceramics, the focus is on the analysis, design, implementation, interpretation, or evaluation of ceramics within Engineering Materials, particularly where the Polymers and Ceramics module establishes its technical context.', 'SSD_COURSE_039_M4_S4', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;